mapper.insert:
INSERT INTO sys_notice_read (notice_id, user_id, read_time) SELECT notice_id, user_id, read_time FROM (
SELECT #{noticeId} as notice_id, #{userId} as user_id, getdate() as read_time
) AS tmp WHERE NOT EXISTS ( SELECT 1 FROM sys_notice_read r WHERE r.notice_id = tmp.notice_id AND r.user_id = tmp.user_id )

mapper.select:
select u.user_id as userId, u.user_name as userName, u.nick_name as nickName, d.dept_name as deptName, u.phonenumber as phonenumber, r.read_time as readTime from sys_notice_read r inner join sys_user u on u.user_id = r.user_id and u.del_flag = '0' left join sys_dept d on d.dept_id = u.dept_id where r.notice_id = #{noticeId}
and ( u.user_name like '%' + #{searchValue} + '%' or u.nick_name like '%' + #{searchValue} + '%' )
order by r.read_time desc
